CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,salt TEXT NOT NULL,hash TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shops(id TEXT PRIMARY KEY,userId TEXT NOT NULL UNIQUE,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,shopId TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,price REAL NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,mediaUrl TEXT NOT NULL,mediaType TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS products_shop_idx ON products(shopId);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,shopId TEXT NOT NULL,code TEXT NOT NULL UNIQUE,customer TEXT NOT NULL,phone TEXT NOT NULL,items TEXT NOT NULL,total REAL NOT NULL,status TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_shop_idx ON orders(shopId);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,userId TEXT NOT NULL,expiresAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(key TEXT PRIMARY KEY,contentType TEXT NOT NULL,data BLOB NOT NULL,createdAt TEXT NOT NULL);
